/** Generated by scripts/bake-splash-logo.py. Distance in world units, IEEE754 half-floats. */
export const LOGO_SIZE = [512, 320];
export const LOGO_COMPRESSED = "";
export async function decodeLogo() {
  const bytes = Uint8Array.from(atob(LOGO_COMPRESSED), c => c.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate'));
  const result = new Uint8Array(await new Response(stream).arrayBuffer());
  if (result.byteLength !== LOGO_SIZE[0]*LOGO_SIZE[1]*2) throw new Error('Invalid logo atlas');
  return result;
}
